import{_ as e,o as s,c as o,a2 as l}from"./chunks/framework.CD2m2Tvf.js";const y=JSON.parse('{"title":"Technology Choices & Exhaustive Trade-Off Comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),a={name:"04-tech-comparisons.md"};function r(n,t,i,d,g,c){return s(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="technology-choices-exhaustive-trade-off-comparisons" tabindex="-1">Technology Choices &amp; Exhaustive Trade-Off Comparisons <a class="header-anchor" href="#technology-choices-exhaustive-trade-off-comparisons" aria-label="Permalink to &quot;Technology Choices &amp; Exhaustive Trade-Off Comparisons&quot;">​</a></h1><h2 id="_1-backend-ingestion-fastapi-vs-go-vs-rust-vs-node-js" tabindex="-1">1. Backend Ingestion: FastAPI vs Go vs Rust vs Node.js <a class="header-anchor" href="#_1-backend-ingestion-fastapi-vs-go-vs-rust-vs-node-js" aria-label="Permalink to &quot;1. Backend Ingestion: FastAPI vs Go vs Rust vs Node.js&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Factor</th><th style="text-align:left;">FastAPI (Python) [Chosen]</th><th style="text-align:left;">Go (net/http)</th><th style="text-align:left;">Rust (Axum / Actix)</th><th style="text-align:left;">Node.js (Express)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Throughput / Latency</strong></td><td style="text-align:left;">High (uvloop async)</td><td style="text-align:left;">Extremely High (goroutines)</td><td style="text-align:left;">Maximum (zero cost)</td><td style="text-align:left;">Moderate (single-threaded)</td></tr><tr><td style="text-align:left;"><strong>ML &amp; AI Integration</strong></td><td style="text-align:left;"><strong>Native (NumPy, PyTorch, LLM APIs)</strong></td><td style="text-align:left;">Clunky (Cgo / Python microservice)</td><td style="text-align:left;">Verbose (Candle / ONNX bindings)</td><td style="text-align:left;">Moderate (JS SDKs)</td></tr><tr><td style="text-align:left;"><strong>Developer Velocity</strong></td><td style="text-align:left;"><strong>Very Rapid (Pydantic, automatic docs)</strong></td><td style="text-align:left;">Rapid</td><td style="text-align:left;">Slower (strict borrow checker)</td><td style="text-align:left;">Rapid</td></tr><tr><td style="text-align:left;"><strong>Memory Footprint</strong></td><td style="text-align:left;">Moderate (~80MB base)</td><td style="text-align:left;">Very Low (~15MB)</td><td style="text-align:left;">Minimal (~5MB)</td><td style="text-align:left;">Moderate (~70MB)</td></tr></tbody></table><ul><li><strong>Why I Used FastAPI</strong>: The distributed tracing platform requires deep coupling between high-speed ingestion and complex statistical machine learning (anomaly scoring, causal graph analysis, LLM incident postmortems). Python provides the richest ecosystem for these ML algorithms while FastAPI&#39;s async runtime delivers thousands of requests per second. [CONFIRM WITH DEVELOPER]</li><li><strong>Trade-off Accepted</strong>: Slightly higher per-core memory usage than Go/Rust, mitigated by horizontal worker scaling.</li></ul><hr><h2 id="_2-telemetry-storage-clickhouse-vs-elasticsearch-vs-postgresql-vs-mongodb" tabindex="-1">2. Telemetry Storage: ClickHouse vs Elasticsearch vs PostgreSQL vs MongoDB <a class="header-anchor" href="#_2-telemetry-storage-clickhouse-vs-elasticsearch-vs-postgresql-vs-mongodb" aria-label="Permalink to &quot;2. Telemetry Storage: ClickHouse vs Elasticsearch vs PostgreSQL vs MongoDB&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Factor</th><th style="text-align:left;">ClickHouse (Columnar) [Chosen Architecture]</th><th style="text-align:left;">Elasticsearch</th><th style="text-align:left;">PostgreSQL</th><th style="text-align:left;">MongoDB</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Data Model</strong></td><td style="text-align:left;">Column-oriented relational</td><td style="text-align:left;">Document / Inverted Index</td><td style="text-align:left;">Row-oriented relational</td><td style="text-align:left;">Document (JSON)</td></tr><tr><td style="text-align:left;"><strong>Compression Ratio</strong></td><td style="text-align:left;"><strong>5x - 10x (ZSTD / Gorilla)</strong></td><td style="text-align:left;">1.5x - 2x</td><td style="text-align:left;">1.2x - 1.5x</td><td style="text-align:left;">1.1x - 1.3x</td></tr><tr><td style="text-align:left;"><strong>Aggregation Speed</strong></td><td style="text-align:left;"><strong>Sub-second over billions of rows</strong></td><td style="text-align:left;">Fast for search, slow for math</td><td style="text-align:left;">Slow over 100M+ rows</td><td style="text-align:left;">Slow over 100M+ rows</td></tr><tr><td style="text-align:left;"><strong>Write Throughput</strong></td><td style="text-align:left;"><strong>1,000,000+ rows/sec bulk inserts</strong></td><td style="text-align:left;">High CPU overhead on Lucene merge</td><td style="text-align:left;">Moderate</td><td style="text-align:left;">Moderate</td></tr></tbody></table><ul><li><strong>Why ClickHouse</strong>: Distributed traces are append-only time-series records. Query patterns always aggregate specific columns (e.g., <code>avg(duration) WHERE service_name = &#39;auth&#39;</code>). Columnar storage stores identical columns together, allowing extreme compression and vector instructions (SIMD) for aggregations.</li><li><strong>Why Not Elasticsearch</strong>: Elasticsearch&#39;s inverted index consumes enormous RAM and storage overhead (often 2x the raw data size). ClickHouse achieves 5x-10x compression on trace data.</li></ul>',8)])])}const f=e(a,[["render",r]]);export{y as __pageData,f as default};
